#include "stdint.h"
#include "string.h"
#include "cpu.h"
#include "bus.h"
#include "instructions.h"

static Instruction base_instructions[256];
static Instruction cb_instructions[256];

Instruction decode_base_opcode(uint8_t opcode)
{
    return base_instructions[opcode];
}

Instruction decode_cb_opcode(uint8_t opcode)
{
    return cb_instructions[opcode];
}


Instruction set_instruction(InstructionHandler handler, uint8_t opcode, 
                            Register dest, Register source, Condition condition, uint8_t bit_number, 
                            int16_t cycles, int16_t extra_cycles, char* name)
{
    Instruction res = {};
    res.handler = handler;
    res.opcode = opcode;
    res.dest = dest;
    res.source = source;
    res.condition = condition;
    res.bit_number = bit_number;
    res.cycles = cycles;
    res.extras_cycles = extra_cycles;
    strcpy(res.name, name);

    return res;
}

